CREATE COLUMN TABLE "TEST_AP"."OPKG" ("PkgCode" INTEGER CS_INT NOT NULL , "PkgType" NVARCHAR(30) NOT NULL , "Length1" DECIMAL(21,6) CS_FIXED, "Len1Unit" SMALLINT CS_INT, "length2" DECIMAL(21,6) CS_FIXED, "Len2Unit" SMALLINT CS_INT, "Width1" DECIMAL(21,6) CS_FIXED, "Wdth1Unit" SMALLINT CS_INT, "Width2" DECIMAL(21,6) CS_FIXED, "Wdth2Unit" SMALLINT CS_INT, "Height1" DECIMAL(21,6) CS_FIXED, "Hght1Unit" SMALLINT CS_INT, "Height2" DECIMAL(21,6) CS_FIXED, "Hght2Unit" SMALLINT CS_INT, "Volume" DECIMAL(21,6) CS_FIXED, "VolUnit" SMALLINT CS_INT, "Weight1" DECIMAL(21,6) CS_FIXED, "WghtUnit" SMALLINT CS_INT, "Weight2" DECIMAL(21,6) CS_FIXED, "Wght2Unit" SMALLINT CS_INT, PRIMARY KEY ("PkgCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OPKG_TYPE" ON "TEST_AP"."OPKG" ( "PkgType" ASC )